use super::*;
use std::{fs,path::PathBuf,time::{SystemTime,UNIX_EPOCH}};
use std::os::unix::fs::PermissionsExt;
use sqlx::sqlite::{SqlitePoolOptions,SqliteConnectOptions,SqliteJournalMode};
pub(super) fn context()->Value{json!({"version":1,"serverBase":"local-vault","accountId":"local-user","sessionId":"general-import-epoch","cacheScope":"local-import-test","storageMode":"local","provider":"none"})}
pub(super) async fn fixture(label:&str)->(PathBuf,Owner,Request){
 let root=std::env::temp_dir().join(format!("starlane-original-local-import-{label}-{}-{}",std::process::id(),SystemTime::now().duration_since(UNIX_EPOCH).unwrap().as_nanos()));
 fs::create_dir(&root).unwrap();fs::set_permissions(&root,fs::Permissions::from_mode(0o700)).unwrap();fs::create_dir(root.join(".starlane")).unwrap();
 let pool=SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(root.join(".starlane/starlane-notes.sqlite3")).create_if_missing(true).journal_mode(SqliteJournalMode::Delete)).await.unwrap();crate::local_database::migrate_database(&pool).await.unwrap();
 let mut tx=pool.begin().await.unwrap();let revision=crate::local_database::write_snapshot_in_tx(&mut tx,"none",&json!({"schema_version":1,"spaces":[{"id":"space","name":"Original local space"}],"documents":[{"id":"page","space_id":"space","title":"Original page","content":"Published original","locked":false}],"drafts":[{"id":"draft-local","document_id":"page","space_id":"space","owner_id":"local-user","title":"Original draft","content":"exact body\r\n<!-- starlane:custom-css -->\r\n.bad{color:red}\r\n<!-- /starlane:custom-css -->\r\n","created_at":"2026-10-16T00:00:00Z","updated_at":"2026-10-16T00:00:00Z","base_updated_at":"original"}],"assets":[],"sync_state":{"state":"idle","updated_at":"original","unknown_extension":{"keep":true},"queued_operations":[{"id":"original-queued-work","entity_type":"document","entity_id":"page","action":"update_content","queued_at":"original","attempts":2,"payload":{"content":"exact original proposal\r\n","unknown":"retain"}}]}})).await.unwrap();tx.commit().await.unwrap();pool.close().await;
 let selection=vault::SnapshotRequestBinding::capture_at(root.with_extension("settings.json"),root.clone(),"none").unwrap();let owner=Owner::capture(selection,"none",&revision,context()).unwrap();
 let request=Request{operation_id:"11111111-1111-4111-8111-111111111111".into(),name:"same-name.bin".into(),mime_type:"application/octet-stream".into(),byte_length:65539,space_id:"space".into(),document_id:"page".into(),draft_id:"draft-local".into(),draft_created_at:"2026-10-16T00:00:00Z".into(),original_binding:owner.binding(),path_source:None};(root,owner,request)
}
async fn pool(root:&PathBuf)->sqlx::SqlitePool{SqlitePoolOptions::new().max_connections(1).connect_with(SqliteConnectOptions::new().filename(root.join(".starlane/starlane-notes.sqlite3"))).await.unwrap()}
async fn snapshot(root:&PathBuf)->Value{let db=pool(root).await;let value=crate::local_database::read_snapshot_from_pool(&db,"none").await.unwrap().unwrap();db.close().await;value}
async fn change(root:&PathBuf,edit:impl FnOnce(&mut Value))->Value{let db=pool(root).await;let mut value=crate::local_database::read_snapshot_from_pool(&db,"none").await.unwrap().unwrap();edit(&mut value);let mut tx=db.begin().await.unwrap();let revision=crate::local_database::write_snapshot_in_tx(&mut tx,"none",&value).await.unwrap();tx.commit().await.unwrap();db.close().await;value["canonical_revision"]=json!(revision);value}
fn fresh(root:&PathBuf,revision:&str)->Owner{let selection=vault::SnapshotRequestBinding::capture_at(root.with_extension("settings.json"),root.clone(),"none").unwrap();Owner::capture(selection,"none",revision,context()).unwrap()}
async fn finish_small(label:&str,lose:bool)->(PathBuf,Owner,Value){let(root,owner,mut request)=fixture(label).await;request.byte_length=3;let creator=owner.clone().prepare_local_import(context(),request).await.unwrap();let(creator,_)=creator.append_owned(context(),0,vec![0,13,10]).await.unwrap();let result=if lose{assert!(creator.finish_losing_ack(context()).await.unwrap_err().contains("acknowledgement lost"));Value::Null}else{creator.finish(context()).await.unwrap()};let saved=snapshot(&root).await;let current=fresh(&root,saved["canonical_revision"].as_str().unwrap());(root,current,result)}

#[tokio::test]async fn genuine_general_chunks_commit_exact_asset_queue_and_immutable_receipt_together(){
 let(root,owner,request)=fixture("winner").await;let before=snapshot(&root).await;
 let creator=owner.prepare_local_import(context(),request).await.unwrap();assert_eq!(creator.proof.created_at.len(),24);assert_eq!(creator.index,0);
 let(creator,ack)=creator.append_owned(context(),0,vec![7;65536]).await.unwrap();assert_eq!(ack["received"],65536);let(creator,_)=creator.append_owned(context(),1,vec![0,13,10]).await.unwrap();let result=creator.finish(context()).await.unwrap();
 let bytes=fs::read(result["asset"]["vault_path"].as_str().unwrap()).unwrap();assert_eq!(&bytes[..65536],vec![7;65536]);assert_eq!(&bytes[65536..],[0,13,10]);
 let saved=snapshot(&root).await;assert_eq!(saved["assets"],json!([result["asset"]]));assert_eq!(saved["documents"],before["documents"]);assert_eq!(saved["drafts"],before["drafts"]);assert_eq!(saved["sync_state"]["unknown_extension"],before["sync_state"]["unknown_extension"]);assert_eq!(saved["sync_state"]["queued_operations"][0],before["sync_state"]["queued_operations"][0]);
 let queued=&saved["sync_state"]["queued_operations"][1];assert_eq!(queued["entity_id"],result["asset"]["id"]);assert_eq!(queued["payload"]["draft_id"],"draft-local");assert_eq!(queued["payload"]["local_draft_source"]["draft_created_at"],"2026-10-16T00:00:00Z");
 let receipt:Value=serde_json::from_str(result["receipt_json"].as_str().unwrap()).unwrap();assert_eq!(receipt["queued_operation"],*queued);
 let db=pool(&root).await;assert!(sqlx::query("DELETE FROM native_local_import_receipts").execute(&db).await.is_err());assert!(sqlx::query("UPDATE native_local_import_intents SET request_json='{}'").execute(&db).await.is_err());db.close().await;fs::remove_dir_all(root).unwrap();
}
