 fs::remove_dir_all(&root).unwrap();let actual=crate::local_database::attachment_download_owner::native_archive_import::Owner::capture(selection.clone(),"none",request,context()).unwrap();actual.with_read(context(),|reader|{let mut bytes=Vec::new();reader.copy_exact(&mut bytes)?;assert_eq!(bytes,[0,13,10]);Ok(())}).await.unwrap();
 let owner=Owner::capture(selection,"none",imported["canonical_revision"].as_str().unwrap(),context()).unwrap();assert!(owner.clone().with_local_import(context(),"11111111-1111-4111-8111-111111111111".into(),|_|Ok(())).await.is_err(),"Portable history must not fabricate original creator authority");
 let output=destination.with_extension("reexport.zip");let path=output.clone();let exported=owner.with_capture(context(),move|capture|{assert!(capture.raw_local_imports.is_empty());assert_eq!(capture.raw_imports.len(),1);let binding=capture.output_binding();let selected=crate::local_database::attachment_download_owner::native_archive_output::test_selection(path,binding.clone())?;crate::local_database::attachment_download_owner::native_archive_output::compose(capture,selected,||Ok(binding.clone()))}).await.unwrap();
 let third=destination.with_extension("third-owner");let(_,third_result)=crate::local_database::joint_archive::tests::import_existing_canonical_archive(&output,third.clone(),false).await;assert_eq!(third_result["candidate"]["sync_state"]["queued_operations"],before["sync_state"]["queued_operations"]);assert_eq!(third_result["candidate"]["drafts"],before["drafts"]);let bytes=fs::read(third_result["candidate"]["assets"][0]["vault_path"].as_str().unwrap()).unwrap();assert_eq!(bytes,[0,13,10]);
 remove_archive(source,publication);remove_archive(output,exported);fs::remove_dir_all(destination).unwrap();fs::remove_dir_all(third).unwrap();
