#[tokio::test]async fn original_path_stream_resume_preserves_source_and_exact_native_request(){
 let _serial=vault::archive_admission::TEST_SERIAL.lock().unwrap_or_else(|e|e.into_inner());
 let(root,owner,mut request)=fixture("path-stream").await;let source_path=root.with_extension("input.bin");let bytes=vec![71;65539];std::fs::write(&source_path,&bytes).unwrap();let before=snapshot(&root).await;
 let metadata=path::metadata(&owner,source_path.to_str().unwrap()).unwrap();assert_eq!(metadata["byte_length"],65539);let base=request.clone();let source=path::Source::capture(&owner,source_path.to_str().unwrap(),None,request.byte_length).unwrap();request.path_source=Some(source.proof.clone());let creator=owner.clone().prepare_local_import(context(),request.clone()).await.unwrap();let(creator,_)=creator.append_owned(context(),0,bytes[..CHUNK].to_vec()).await.unwrap();drop(creator);drop(source);
 // Native SQL readback recovers the enriched request after a missing IPC reply.
 let recovered=owner.clone().path_request(context(),base).await.unwrap();assert_eq!(serde_json::to_value(&recovered).unwrap(),serde_json::to_value(&request).unwrap());let proof=recovered.path_source.as_ref().unwrap();let source=path::Source::capture(&owner,source_path.to_str().unwrap(),Some(proof),request.byte_length).unwrap();let creator=owner.resume_local_import(context(),recovered).await.unwrap();let ack=source.run(creator,context()).await.unwrap();assert_eq!(std::fs::read(&source_path).unwrap(),bytes);assert_eq!(std::fs::read(ack["asset"]["vault_path"].as_str().unwrap()).unwrap(),bytes);
 let saved=snapshot(&root).await;assert_eq!(saved["drafts"],before["drafts"]);assert_eq!(saved["sync_state"]["queued_operations"][0],before["sync_state"]["queued_operations"][0]);let receipt:Value=serde_json::from_str(ack["receipt_json"].as_str().unwrap()).unwrap();assert_eq!(receipt["request"]["path_source"],serde_json::to_value(request.path_source.clone().unwrap()).unwrap());assert_eq!(receipt["request"]["path_source"]["binary_sha256"],serde_json::from_str::<Value>(receipt["seal_json"].as_str().unwrap()).unwrap()["binary_sha256"]);
 let current=fresh(&root,saved["canonical_revision"].as_str().unwrap());let(archive,report)=publish(&root,current,"path-import.zip").await;let prepared=vault::archive_admission::prepare("none",&archive,&root.with_extension("path-preview").join("assets")).unwrap();assert_eq!(serde_json::from_str::<Value>(&prepared.snapshot_json).unwrap()["sync_state"]["queued_operations"],saved["sync_state"]["queued_operations"]);vault::archive_admission::cancel("none",&prepared.handle).unwrap();remove_archive(archive,report);
 std::fs::remove_file(source_path).unwrap();std::fs::remove_dir_all(root).unwrap();
}
